  for (let i = 1; i <= doc.numPages; i++) {
    const page = await doc.getPage(i)
    try {
      const textContent = await page.getTextContent()
      const parts: string[] = []
      for (const item of textContent.items) if ('str' in item) {
        length += item.str.length + 1
        if (length > LIMITS.textChars) throw Error('Extracted PDF text limit exceeded')
